RAW_SHA='118768f119b95b02ff49612456d560d0c9b61ba0babbfa0bbd15a3c998f79732'
RETAIL_SHA='ab73ebebd304b1fe9ab1520ef08538094ee3a0ea053deceb4d84f0035e0c9dca'
BINDINGS={24: [('R_MIPS_HI16', 'D_800CC2D0')], 68: [('R_MIPS_LO16', 'D_800CC2D0')], 108: [('R_MIPS_HI16', 'D_800A3730')], 164: [('R_MIPS_LO16', 'D_800A3730')], 216: [('R_MIPS_26', 'sinf')], 260: [('R_MIPS_26', 'cosf')]}

ROOT=Path(__file__).resolve().parents[2]
sha=lambda b:hashlib.sha256(b).hexdigest()
def freeze(root,out):
    allowed={SOURCE,OBJECT,CALLER_SOURCE,ELF,'conker/build/conker.us.bin'}
    for name,h in FROZEN.items():
        p=out/'frozen'/name
        if not p.exists():
            data=(root/name).read_bytes()
            if sha(data)!=h:raise ValueError('Secondary-camera initial input changed: '+name)
            p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
        if sha(p.read_bytes())!=h or name not in allowed and sha((root/name).read_bytes())!=h:
            raise ValueError('Secondary-camera frozen input changed: '+name)
    return FROZEN
def source_states(live):
    old=(ROOT/BUILD/'frozen'/SOURCE).read_text()
    if sha((ROOT/BUILD/'frozen'/SOURCE).read_bytes())!=FROZEN[SOURCE]:raise ValueError('Secondary-camera predecessor changed')
    if live not in(old,NEW_SOURCE):raise ValueError('Secondary-camera live source changed')
    return old,NEW_SOURCE,live==NEW_SOURCE
def caller_states(live):
    old=(ROOT/BUILD/'frozen'/CALLER_SOURCE).read_text()
    if sha((ROOT/BUILD/'frozen'/CALLER_SOURCE).read_bytes())!=FROZEN[CALLER_SOURCE]:raise ValueError('Secondary-camera caller predecessor changed')
    new=old.replace('extern void func_1512A360(u8 *);','extern void func_1512A360(u8 *);\nextern void func_1512E4B0(struct108 *);').replace('func_1512E4B0(address);','func_1512E4B0((struct108 *)address);')
    if old==new or live not in(old,new):raise ValueError('Secondary-camera live caller changed')
    return old,new,live==new
def payload(obj):
    t,fs,rs=parse_object(obj);f=fs[FUNCTION];start,size=f['value'],f['size']
    return t[start:start+size],{a-start:v for a,v in rs.items()if start<=a<start+size}
def checked(raw,refs):
    if len(raw)!=SIZE or sha(raw)!=RAW_SHA or refs!=BINDINGS:raise ValueError('Secondary-camera raw body/bindings changed')
    return raw,refs
def strict_image(before,actual,truth):
    if sha(before)!=FROZEN[ELF]or len(truth)!=SLOT_SIZE or sha(truth)!=RETAIL_SHA:raise ValueError('Secondary-camera strict inputs changed')
    expected=bytearray(before);at=elf_slot_offset(before,ENTRY,SLOT_SIZE);expected[at:at+SLOT_SIZE]=truth
    row=[(p,v)for p,n,v,_ in symbol_rows(expected)if n==FUNCTION]
    if len(row)!=1 or row[0][1][1:3]!=(ENTRY,12):raise ValueError('Secondary-camera predecessor extent changed')
    struct.pack_into('>I',expected,row[0][0]+8,SIZE)
    if bytes(expected)!=actual:raise ValueError('Secondary-camera whole image differs from body/extent prediction')
    return sum(a!=b for a,b in zip(before,actual))

def prepare(root=ROOT):
    root=Path(root).resolve();out=root/BUILD;out.mkdir(parents=True,exist_ok=True);freeze(root,out)
    old,new,installed=source_states((root/SOURCE).read_text())
    caller_old,caller_new,caller_installed=caller_states((root/CALLER_SOURCE).read_text());assert installed==caller_installed
    (out/'proposed-owner.c').write_text(new);(out/'proposed-caller.c').write_text(caller_new)
    before,od=compile_owner(root,out,old,'predecessor-owner');after,nd=compile_owner(root,out,new,'qualified-owner');assert not od and not nd
    cb,cd=compile_owner(root,out,caller_old,'predecessor-caller');ca,ce=compile_owner(root,out,caller_new,'qualified-caller');assert shared.diagnostic_rows(cd)==shared.diagnostic_rows(ce) and sum(shared.diagnostic_rows(cd).values())==5
    assert same_functions(cb,ca)==45 and normalized_pools(cb)==normalized_pools(ca) and sections(cb)['.reginfo']==sections(ca)['.reginfo']
    assert same_functions(before,after,(FUNCTION,))==0
    rom=(root/'conker/conker.us.bin').read_bytes();truth=rom[0x15B960:0x15BAA0]
    with patch.multiple(shared,FUNCTION=FUNCTION,OWNER='generated_15B960',SOURCE=SOURCE,OBJECT=OBJECT,ASM='conker/asm/15B960.s',ENTRY=0x1512E4B0):
     raw,refs=checked(*payload(after));syms={n:({'sinf':0x15047D60,'cosf':0x15047C00}[n]if n in('sinf','cosf')else int(n.split('_')[1],16))for rows in refs.values()for _,n in rows}
     assert len(raw)==308 and struct.pack('>77I',*bound_blob(raw,refs,syms))==truth[:308]
     oldpad=shared.padded(root,out,before,'predecessor-padded',True);newpad=shared.padded(root,out,after,'qualified-padded',True)
     independent=shared.padded(root,out,after,'independent-padded');assert same_functions(newpad,independent)==1
     assert normalized_pools(oldpad)==normalized_pools(newpad)==normalized_pools(independent)
     assert (root/OBJECT).read_bytes()==(newpad if installed else oldpad).read_bytes() and shared.payload(newpad)==(raw,refs)
     registers=[struct.unpack('>6I',sections(p)['.reginfo'][1])for p in(before,after)]
     assert registers[1][5]==registers[0][5]
     owner_recipe=shared.make_shadow(root,out,out/'proposed-owner.c',newpad,after,SOURCE,OBJECT,'owner-Make',nd,False)
    with patch.multiple(shared,FUNCTION=caller.FUNCTION,OWNER='game_14FF90',SOURCE=caller.SOURCE,OBJECT=caller.OBJECT,ASM=caller.ASM if hasattr(caller,'ASM')else'conker/asm/nonmatchings/game_14FF90/func_15128540.s',ENTRY=caller.ENTRY):
     cbp=shared.padded(root,out,cb,'predecessor-caller-padded');cap=shared.padded(root,out,ca,'qualified-caller-padded')
     assert cbp.read_bytes()==cap.read_bytes()==(root/caller.OBJECT).read_bytes()
     caller_recipe=caller.make_shadow(root,out,out/'proposed-caller.c',cap,ca,caller.SOURCE,caller.OBJECT,'caller-Make',ce,False)
    canonical=[]
    for name,p in(('old',oldpad),('new',newpad)):
     q=out/('canonical-'+name)/'generated_15B960.c.o';q.parent.mkdir(exist_ok=True);q.write_bytes(p.read_bytes());canonical.append(q)
    with patch.multiple(shared.linker,FILENAME='generated_15B960',OBJECT=OBJECT,LINKER='conker/build/conker.ld'):
     oldelf=shared.linker.link_image(root,out,canonical[0],'predecessor-image');newelf=shared.linker.link_image(root,out,canonical[1],'qualified-image')
    assert (newelf if installed else oldelf).read_bytes()==(root/ELF).read_bytes()
    a,_,aa=load_elf_functions(str(oldelf),'mips-linux-gnu-objdump');b,_,bb=load_elf_functions(str(newelf),'mips-linux-gnu-objdump')
    assert a.keys()==b.keys()and aa==bb and[n for n in b if a[n]!=b[n]]==[FUNCTION]
    assert b[FUNCTION]==list(struct.unpack('>80I',truth))
    expected=bytearray(oldelf.read_bytes());at=elf_slot_offset(expected,0x1512E4B0,320);expected[at:at+320]=truth
    row=[(p,v)for p,n,v,_ in symbol_rows(expected)if n==FUNCTION];assert len(row)==1 and row[0][1][2]==12
    struct.pack_into('>I',expected,row[0][0]+8,308)
    actual=newelf.read_bytes();delta=strict_image(oldelf.read_bytes(),actual,truth);different=[i for i,(x,y)in enumerate(zip(expected,actual))if x!=y]
    oldrows=symbol_rows(expected);newrows=symbol_rows(actual);assert sorted((n,v[1:])for _,n,v,_ in oldrows)==sorted((n,v[1:])for _,n,v,_ in newrows)
    changes=[dict(index=i,old=x[1],new=y[1],old_at=x[0],new_at=y[0])for i,(x,y)in enumerate(zip(oldrows,newrows))if x[1]!=y[1]]
    layout=audit_layout(newelf,root/'conker');assert layout['exact']and layout['different_bytes']==0
    report=dict(words=77,slot_words=80,padding_words=3,frame=40,guards=0,owner_diagnostics=0,caller_inherited_diagnostics=5,
     raw_neighbors=0,padded_neighbors=0,caller_functions_fixed=45,caller_object_fixed=True,owner_Make=owner_recipe,caller_Make=caller_recipe,
     source_installed=installed,frozen_inputs=len(FROZEN),strict_changed_bytes=delta,exclusions=0,strict_unexplained_bytes=len(different),metadata_rows=changes,functions=len(a),all_addresses_fixed=True,protected_data=layout,
     raw_sha256=shared.sha(raw),refs=refs,ELF_sha256=shared.sha(actual),owner_sha256=shared.sha(newpad.read_bytes()),
     caller_object_sha256=shared.sha(cap.read_bytes()),image_changed_bytes=sum(x!=y for x,y in zip(oldelf.read_bytes(),actual)))

    assert delta==260 and not changes
    (out/'qualification.json').write_text(json.dumps(report,indent=2)+'\n')
    return dict(report=report,raw=raw,refs=refs,qualified_object=newpad,predecessor_elf=oldelf,qualified_elf=newelf)

if __name__=='__main__':print(json.dumps(prepare()['report'],indent=2))
